css:
[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
@keyframes sf-pulse{0%{opacity:.75}100%{opacity:1}}
[data-chat-canvas]{background-image:radial-gradient(ellipse 70% 45% at 50% 105%,rgba(255,110,20,.2),rgba(255,70,0,.06) 55%,transparent 75%)!important}
[data-slot="composer-host"]{box-shadow:0 0 0 1px rgba(255,159,28,.28),0 12px 44px -12px rgba(255,120,20,.45);animation:sf-pulse 4s ease-in-out infinite alternate}
@media (prefers-reduced-motion:reduce){[data-slot="composer-host"]{animation:none!important}}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{color:#ffb54d}
::selection{background:rgba(255,159,28,.32)}
